from functools import wraps

from taf.gnb.oam.coam.vdu.exceptions import ApiException


def provide_fresh_token(func, api_exception):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            if api_exception:
                self.configuration.access_token = self.token_storage.access_token
            return func(self, *args, **kwargs)

        except Exception as e:
            if not _is_handled_exception(e, api_exception):
                raise

            if _should_refresh_token(e):
                _refresh_token(self, api_exception)
                return func(self, *args, **kwargs)
            else:
                raise

    return wrapper


def auto_token_refresh(api_exception=None):
    """Decorator that refreshes token and retries on ApiException + optionally one extra exception."""
    def decorator(cls):
        for attr_name, attr_value in cls.__dict__.items():
            if callable(attr_value) and not attr_name.startswith("_"):
                wrapped_method = provide_fresh_token(attr_value, api_exception)
                setattr(cls, attr_name, wrapped_method)
        return cls
    return decorator


def _is_handled_exception(e, api_exception):
    handled = (ApiException,)
    if api_exception:
        handled += (api_exception,)
    return isinstance(e, handled)


def _should_refresh_token(exception):
    m2m_disabled_msg = "Machine-to-Machine interface was disabled"

    status = getattr(exception, 'status', None)
    msg = getattr(exception, 'body', None)

    if msg:
        return status in [401, 403] and m2m_disabled_msg not in msg

    else:
        return status in [401, 403]


def _refresh_token(self, api_exception):
    self.sec.login(username=self.con_details.username, password=self.con_details.password)
    if api_exception:
        self.configuration.access_token = self.token_storage.access_token
